<?php
if (!defined('ABSPATH')) exit;
function gim_run_assurance($job_id){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job)return new WP_Error('job','Job not found.'); $find=[];$score=0;
 if($job->status!=='completed'){ $find[]=['severity'=>'CRITICAL','code'=>'CUSTOMER_COMPLETION_MISSING'];$score+=100; }
 $captured=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".gim_table('payments')." WHERE job_id=%d AND purpose='initial_service' AND status IN ('captured','partially_refunded','refunded')",$job_id)); if(!$captured){$find[]=['severity'=>'CRITICAL','code'=>'INITIAL_PAYMENT_NOT_CAPTURED'];$score+=100;}
 $openaw=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".gim_table('additional_work')." WHERE job_id=%d AND status IN ('proposed','customer_approved','payment_pending')",$job_id)); if($openaw){$find[]=['severity'=>'CRITICAL','code'=>'ADDITIONAL_WORK_UNRESOLVED'];$score+=100;}
 $mat=gim_material_plan($job_id); if($mat&&$mat->ai_decision==='BLOCK'){$find[]=['severity'=>'CRITICAL','code'=>'MATERIAL_AI_BLOCK'];$score+=100;} elseif($mat&&$mat->ai_decision==='REVIEW_REQUIRED'){$find[]=['severity'=>'MEDIUM','code'=>'MATERIAL_AI_REVIEW'];$score+=25;}
 $disp=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".gim_table('disputes')." WHERE job_id=%d AND status NOT IN ('resolved','closed')",$job_id)); if($disp){$find[]=['severity'=>'MEDIUM','code'=>'ACTIVE_DISPUTE'];$score+=30;}
 $decision=array_filter($find,fn($f)=>$f['severity']==='CRITICAL')?'BLOCK':($score>=20?'REVIEW_REQUIRED':'PASS'); $input=hash('sha256',gim_json([$job,$captured,$openaw,$mat,$disp])); $out=hash('sha256',gim_json([$decision,$score,$find])); $wpdb->insert(gim_table('assurance_runs'),['job_id'=>$job_id,'engine_version'=>'gim-sta-v1','decision'=>$decision,'risk_score'=>min(100,$score),'input_digest'=>$input,'output_digest'=>$out,'findings_json'=>gim_json($find),'created_at'=>gim_now()]); gim_audit('sta.completed','job',$job->reference,['decision'=>$decision]); return ['decision'=>$decision,'score'=>min(100,$score),'findings'=>$find]; }
